#include "hardware/BenchOnlyNeuralHardwareAdapter.h"
namespace dnxr { BenchOnlyHardwareDecision BenchOnlyNeuralHardwareAdapter::validate(const BenchOnlyHardwareRequest& r) const { BenchOnlyHardwareDecision d; if(r.humanSubjectAttached){ d.reason="Rejected: human subject attachment is not permitted in bench-only adapter."; return d; } if(r.allowStimulusDispatch){ d.reason="Rejected: neural stimulus dispatch is disabled for 0.6.5."; return d; } if(r.missingPhysicalCutoff){ d.reason="Rejected: physical cutoff is required for bench operation."; return d; } if(r.missingAckLine){ d.reason="Rejected: explicit ACK line is required for bench operation."; return d; } d.accepted=true; d.reason="Accepted for phantom/loopback bench-only operation."; return d; } }
